await page.goto('/login');
await expect(page.getByRole('main').first()).toBeVisible();

const report = await page.evaluate(() => {
  const clips = (v) => v === 'hidden' || v === 'clip';
  const all = Array.from(document.querySelectorAll('body *'));
  const match = (el, word) => {
    const s = `${el.className && el.className.baseVal !== undefined ? el.className.baseVal : el.className} ${el.id} ${el.getAttribute('data-testid') || ''}`.toLowerCase();
    return s.includes(word);
  };
  const page = all.filter((el) => match(el, 'landing') && !match(el, 'band'));
  const band = all.filter((el) => match(el, 'band'));
  const info = (els) => els.map((el) => {
    const cs = getComputedStyle(el);
    return { tag: el.tagName, cls: String(el.className), ox: cs.overflowX, oy: cs.overflowY, clips: clips(cs.overflowX) || clips(cs.overflowY) };
  });
  return { page: info(page), band: info(band) };
});

// the landing page container and the landing band must both clip their overflow
expect(report.page.length + report.band.length).toBeGreaterThan(0);
const unclipped = [...report.page, ...report.band].filter((e) => !e.clips);
if (report.band.length) {
  expect(report.band.some((e) => e.clips)).toBe(true);
}
if (report.page.length) {
  expect(report.page.some((e) => e.clips)).toBe(true);
}
expect(unclipped.length < report.page.length + report.band.length || unclipped.length === 0).toBe(true);
